def check_no_lookahead(px, period=20, pnl_fn=None):
    fn = pnl_fn or pnl_ma
    head = px.iloc[:-20]
    full_run = fn(px, period=period, cost_bps=2)
    head_run = fn(head, period=period, cost_bps=2)
