def regime_stats(r, signal, bad_mask, q=0.33):
    lo = float(signal.quantile(q))
    hi = float(signal.quantile(1 - q))
    masks = {"低": signal <= lo, "中": (signal > lo) & (signal <= hi), "高": signal > hi}
